create extension if not exists pgcrypto;
create table public.locations(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,name text not null check(length(trim(name))>0),parent_id uuid,version int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,owner_id),foreign key(parent_id,owner_id) references public.locations(id,owner_id) on delete restrict);
create table public.box_number_counters(owner_id uuid primary key references auth.users(id) on delete cascade,next_number bigint not null default 1 check(next_number>0));
create table public.boxes(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,box_number bigint not null check(box_number>0),location_id uuid not null,description text,capacity_l numeric check(capacity_l>=0),version int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,box_number),unique(id,owner_id),foreign key(location_id,owner_id) references public.locations(id,owner_id) on delete restrict);
create table public.items(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,name text not null check(length(trim(name))>0),notes text,tags text[] not null default '{}',quantity numeric check(quantity>=0),quantity_unit text,quantity_approximate boolean not null default false,volume_l numeric check(volume_l>=0),location_id uuid,box_id uuid,archived boolean not null default false,archived_at timestamptz,version int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,owner_id),check((location_id is not null)::int+(box_id is not null)::int=1),check((archived and archived_at is not null) or (not archived and archived_at is null)),foreign key(location_id,owner_id) references public.locations(id,owner_id) on delete restrict,foreign key(box_id,owner_id) references public.boxes(id,owner_id) on delete restrict);
create table public.item_photos(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,item_id uuid not null,object_path text not null unique,sort_order int not null default 0,is_cover boolean not null default false,created_at timestamptz not null default now(),check(split_part(object_path,'/',1)=owner_id::text and split_part(object_path,'/',2)=item_id::text),foreign key(item_id,owner_id) references public.items(id,owner_id) on delete cascade);
create index items_owner_created on public.items(owner_id,created_at desc);create index items_owner_box on public.items(owner_id,box_id);create index items_owner_location on public.items(owner_id,location_id);create index items_tags on public.items using gin(tags);create index locations_owner on public.locations(owner_id);create index boxes_location on public.boxes(owner_id,location_id);
alter table public.items add column search_document tsvector not null default ''::tsvector;
create index items_search on public.items using gin(search_document);
create or replace function public.update_item_search_document() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$ begin new.search_document:=to_tsvector('simple',coalesce(new.name,'')||' '||coalesce(new.notes,'')||' '||coalesce(array_to_string(new.tags,' '),'')); return new; end $$;
revoke all on function public.update_item_search_document() from public,anon,authenticated;create trigger items_search_document before insert or update of name,notes,tags on public.items for each row execute function public.update_item_search_document();
create or replace function public.search_item_ids(search_text text) returns setof uuid language sql security invoker set search_path=public,pg_temp as $$ select i.id from public.items i left join public.boxes b on b.id=i.box_id and b.owner_id=i.owner_id left join public.locations direct_l on direct_l.id=i.location_id and direct_l.owner_id=i.owner_id left join public.locations box_l on box_l.id=b.location_id and box_l.owner_id=b.owner_id where i.owner_id=auth.uid() and to_tsvector('simple',coalesce(i.name,'')||' '||coalesce(i.notes,'')||' '||array_to_string(i.tags,' ')||' '||coalesce(b.description,'')||' '||coalesce(b.box_number::text,'')||' '||coalesce(direct_l.name,'')||' '||coalesce(box_l.name,'')) @@ websearch_to_tsquery('simple',search_text) $$;
revoke all on function public.search_item_ids(text) from public,anon;grant execute on function public.search_item_ids(text) to authenticated;
create or replace function public.item_ids_at_location(target_location_id uuid) returns setof uuid language sql security invoker set search_path=public,pg_temp as $$ select i.id from public.items i where i.owner_id=auth.uid() and (i.location_id=target_location_id or exists(select 1 from public.boxes b where b.id=i.box_id and b.location_id=target_location_id and b.owner_id=auth.uid())) $$;
revoke all on function public.item_ids_at_location(uuid) from public,anon;grant execute on function public.item_ids_at_location(uuid) to authenticated;
create or replace function public.box_estimates() returns table(box_id uuid,known_volume_l numeric,missing_estimate_count bigint) language sql security invoker set search_path=public,pg_temp as $$ select b.id,coalesce(sum(i.volume_l) filter(where not i.archived and i.volume_l is not null),0),count(i.id) filter(where not i.archived and i.volume_l is null) from public.boxes b left join public.items i on i.box_id=b.id and i.owner_id=b.owner_id where b.owner_id=auth.uid() group by b.id $$;
revoke all on function public.box_estimates() from public,anon;grant execute on function public.box_estimates() to authenticated;
create or replace function public.allocate_box_number() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ declare n bigint; begin if auth.uid() is null or new.owner_id<>auth.uid() then raise exception 'owner mismatch'; end if; if current_setting('app.inventory_restore',true)='on' then if new.box_number is null or new.box_number<=0 then raise exception 'invalid restored box number'; end if; insert into public.box_number_counters(owner_id,next_number) values(new.owner_id,new.box_number+1) on conflict(owner_id) do update set next_number=greatest(box_number_counters.next_number,excluded.next_number); return new; end if; if new.box_number is not null then raise exception 'box_number is server assigned'; end if; insert into public.box_number_counters(owner_id,next_number) values(new.owner_id,2) on conflict(owner_id) do update set next_number=box_number_counters.next_number+1 returning next_number-1 into n; new.box_number:=n; return new; end $$;
revoke all on function public.allocate_box_number() from public,anon,authenticated;create trigger boxes_number before insert on public.boxes for each row execute function public.allocate_box_number();
create or replace function public.check_location_cycle() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$ begin perform pg_advisory_xact_lock(hashtextextended(new.owner_id::text,0)); if new.parent_id=new.id or (new.parent_id is not null and exists(with recursive descendants(id) as(select new.id union all select l.id from public.locations l join descendants d on l.parent_id=d.id where l.owner_id=new.owner_id and l.id<>new.id) select 1 from descendants where id=new.parent_id)) then raise exception 'Location nesting cannot contain a cycle'; end if; return new; end $$;
revoke all on function public.check_location_cycle() from public,anon,authenticated;create trigger locations_no_cycle before insert or update of parent_id on public.locations for each row execute function public.check_location_cycle();
create or replace function public.touch_version() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$ begin if current_setting('app.inventory_restore',true)='on' then return new; end if; new.updated_at=now(); if row(new.*) is distinct from row(old.*) then new.version=old.version+1; end if; return new; end $$;
revoke all on function public.touch_version() from public,anon,authenticated;create trigger locations_version before update on public.locations for each row execute function public.touch_version();create trigger boxes_version before update on public.boxes for each row execute function public.touch_version();create trigger items_version before update on public.items for each row execute function public.touch_version();
create or replace function public.serialize_inventory_write() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$ begin if new.owner_id is distinct from auth.uid() then raise exception 'owner mismatch'; end if; perform pg_advisory_xact_lock(hashtextextended(new.owner_id::text,0)); return new; end $$;
revoke all on function public.serialize_inventory_write() from public,anon,authenticated;create trigger locations_owner_lock before insert on public.locations for each row execute function public.serialize_inventory_write();create trigger boxes_owner_lock before insert on public.boxes for each row execute function public.serialize_inventory_write();create trigger items_owner_lock before insert on public.items for each row execute function public.serialize_inventory_write();create trigger photos_owner_lock before insert on public.item_photos for each row execute function public.serialize_inventory_write();
create or replace function public.protect_box_number() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$ begin if current_setting('app.inventory_restore',true)='on' then return new; end if; if new.box_number<>old.box_number or new.owner_id<>old.owner_id then raise exception 'box number and owner are immutable'; end if; return new; end $$;
revoke all on function public.protect_box_number() from public,anon,authenticated;create trigger boxes_immutable before update on public.boxes for each row execute function public.protect_box_number();
alter table public.locations enable row level security;alter table public.boxes enable row level security;alter table public.items enable row level security;alter table public.item_photos enable row level security;alter table public.box_number_counters enable row level security;
create policy locations_owner on public.locations for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());create policy boxes_owner on public.boxes for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());create policy items_owner on public.items for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());create policy photos_owner on public.item_photos for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());create policy counter_read on public.box_number_counters for select to authenticated using(owner_id=auth.uid());
grant select,insert,update,delete on public.locations,public.boxes,public.items,public.item_photos to authenticated;
revoke all on public.box_number_counters from anon,authenticated;grant select on public.box_number_counters to authenticated;
create or replace function public.move_items_atomic(item_ids uuid[],destination_id uuid,destination_type text) returns int language plpgsql security invoker set search_path=public,pg_temp as $$ declare n int; begin if destination_type not in ('box','location') then raise exception 'invalid destination type'; end if; if destination_type='box' and not exists(select 1 from public.boxes where id=destination_id and owner_id=auth.uid()) then raise exception 'destination box unavailable'; end if; if destination_type='location' and not exists(select 1 from public.locations where id=destination_id and owner_id=auth.uid()) then raise exception 'destination location unavailable'; end if; if destination_type='box' then update public.items set box_id=destination_id,location_id=null where id=any(item_ids) and owner_id=auth.uid(); else update public.items set location_id=destination_id,box_id=null where id=any(item_ids) and owner_id=auth.uid(); end if; get diagnostics n=row_count; if n<>cardinality(item_ids) then raise exception 'one or more selected items are unavailable; no items moved'; end if; return n; end $$;
revoke all on function public.move_items_atomic(uuid[],uuid,text) from public,anon;grant execute on function public.move_items_atomic(uuid[],uuid,text) to authenticated;
create or replace function public.reorder_item_photos(target_item_id uuid,ordered_photo_ids uuid[],cover_photo_id uuid) returns void language plpgsql security invoker set search_path=public,pg_temp as $$ declare n int; begin select count(*) into n from public.item_photos where item_id=target_item_id and owner_id=auth.uid(); if ordered_photo_ids is null or cardinality(ordered_photo_ids)=0 or cover_photo_id is null or n<>cardinality(ordered_photo_ids) or cardinality(ordered_photo_ids)<>(select count(distinct u.id)::int from unnest(ordered_photo_ids) u(id)) or not (cover_photo_id=any(ordered_photo_ids)) then raise exception 'photo list changed; reload and retry'; end if; if exists(select 1 from unnest(ordered_photo_ids) u(id) where not exists(select 1 from public.item_photos p where p.id=u.id and p.item_id=target_item_id and p.owner_id=auth.uid())) then raise exception 'photo list unavailable'; end if; update public.item_photos p set sort_order=x.ordinality-1,is_cover=(p.id=cover_photo_id) from unnest(ordered_photo_ids) with ordinality x(id,ordinality) where p.id=x.id and p.item_id=target_item_id and p.owner_id=auth.uid(); end $$;
revoke all on function public.reorder_item_photos(uuid,uuid[],uuid) from public,anon;grant execute on function public.reorder_item_photos(uuid,uuid[],uuid) to authenticated;
create or replace function public.restore_inventory(archive_payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid; result jsonb; minimum_imported_box bigint; begin uid:=auth.uid(); if uid is null then raise exception 'authentication required'; end if; if archive_payload->>'schema' is distinct from 'home-storage-inventory' or (archive_payload->>'version')::int is distinct from 1 then raise exception 'unsupported archive schema'; end if; if jsonb_typeof(archive_payload#>'{data,locations}') is distinct from 'array' or jsonb_typeof(archive_payload#>'{data,boxes}') is distinct from 'array' or jsonb_typeof(archive_payload#>'{data,items}') is distinct from 'array' or jsonb_typeof(archive_payload#>'{data,item_photos}') is distinct from 'array' then raise exception 'archive data arrays are missing'; end if; perform pg_advisory_xact_lock(hashtextextended(uid::text,0)); if exists(select 1 from public.locations where owner_id=uid) or exists(select 1 from public.boxes where owner_id=uid) or exists(select 1 from public.items where owner_id=uid) or exists(select 1 from public.item_photos where owner_id=uid) then raise exception 'restore requires an empty inventory'; end if; select min((v->>'box_number')::bigint) into minimum_imported_box from jsonb_array_elements(archive_payload#>'{data,boxes}') v; if minimum_imported_box is not null and exists(select 1 from public.box_number_counters where owner_id=uid and next_number>minimum_imported_box) then raise exception 'restored box numbers would reuse previously allocated numbers'; end if; if exists(select 1 from jsonb_to_recordset(archive_payload#>'{data,item_photos}') as p(object_path text,item_id uuid) where split_part(p.object_path,'/',1)<>uid::text or split_part(p.object_path,'/',2)<>p.item_id::text or not exists(select 1 from storage.objects o where o.bucket_id='inventory-photos' and o.name=p.object_path and o.owner_id=uid::text)) then raise exception 'restore photo is missing or not owned by this account'; end if; perform set_config('app.inventory_restore','on',true); insert into public.locations(id,owner_id,name,parent_id,version,created_at,updated_at) select x.id,uid,x.name,null,coalesce(x.version,1),coalesce(x.created_at,now()),coalesce(x.updated_at,now()) from jsonb_to_recordset(archive_payload#>'{data,locations}') as x(id uuid,name text,version int,created_at timestamptz,updated_at timestamptz); update public.locations l set parent_id=x.parent_id from jsonb_to_recordset(archive_payload#>'{data,locations}') as x(id uuid,parent_id uuid) where l.id=x.id and l.owner_id=uid; insert into public.boxes(id,owner_id,box_number,location_id,description,capacity_l,version,created_at,updated_at) select x.id,uid,x.box_number,x.location_id,x.description,x.capacity_l,coalesce(x.version,1),coalesce(x.created_at,now()),coalesce(x.updated_at,now()) from jsonb_to_recordset(archive_payload#>'{data,boxes}') as x(id uuid,box_number bigint,location_id uuid,description text,capacity_l numeric,version int,created_at timestamptz,updated_at timestamptz); insert into public.items(id,owner_id,name,notes,tags,quantity,quantity_unit,quantity_approximate,volume_l,location_id,box_id,archived,archived_at,version,created_at,updated_at) select x.id,uid,x.name,x.notes,coalesce(x.tags,'{}'),x.quantity,x.quantity_unit,coalesce(x.quantity_approximate,false),x.volume_l,x.location_id,x.box_id,coalesce(x.archived,false),x.archived_at,coalesce(x.version,1),coalesce(x.created_at,now()),coalesce(x.updated_at,now()) from jsonb_to_recordset(archive_payload#>'{data,items}') as x(id uuid,name text,notes text,tags text[],quantity numeric,quantity_unit text,quantity_approximate boolean,volume_l numeric,location_id uuid,box_id uuid,archived boolean,archived_at timestamptz,version int,created_at timestamptz,updated_at timestamptz); insert into public.item_photos(id,owner_id,item_id,object_path,sort_order,is_cover,created_at) select x.id,uid,x.item_id,x.object_path,coalesce(x.sort_order,0),coalesce(x.is_cover,false),coalesce(x.created_at,now()) from jsonb_to_recordset(archive_payload#>'{data,item_photos}') as x(id uuid,item_id uuid,object_path text,sort_order int,is_cover boolean,created_at timestamptz); perform set_config('app.inventory_restore','off',true); result:=jsonb_build_object('locations',jsonb_array_length(archive_payload#>'{data,locations}'),'boxes',jsonb_array_length(archive_payload#>'{data,boxes}'),'items',jsonb_array_length(archive_payload#>'{data,items}'),'item_photos',jsonb_array_length(archive_payload#>'{data,item_photos}')); return result; end $$;
revoke all on function public.restore_inventory(jsonb) from public,anon;grant execute on function public.restore_inventory(jsonb) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('inventory-photos','inventory-photos',false,15728640,array['image/jpeg']) on conflict(id) do update set public=false;
create policy inventory_photo_read on storage.objects for select to authenticated using(bucket_id='inventory-photos' and owner_id=(select auth.uid()::text) and (storage.foldername(name))[1]=(select auth.uid()::text) and (storage.foldername(name))[2]~'^[0-9a-fA-F-]{36}$');
create policy inventory_photo_insert on storage.objects for insert to authenticated with check(bucket_id='inventory-photos' and (storage.foldername(name))[1]=(select auth.uid()::text) and (storage.foldername(name))[2]~'^[0-9a-fA-F-]{36}$');
create policy inventory_photo_delete on storage.objects for delete to authenticated using(bucket_id='inventory-photos' and owner_id=(select auth.uid()::text) and (storage.foldername(name))[1]=(select auth.uid()::text) and (storage.foldername(name))[2]~'^[0-9a-fA-F-]{36}$');
